document.addEventListener("DOMContentLoaded",function(){const targetDate=new Date("2027-08-06T00:00:00");const today=new Date;const diffTime=targetDate-today;const diffDays=Math.ceil(diffTime/(1e3*60*60*24));function setStatus(id,text){const el=document.getElementById(id);if(el)el.innerHTML=text}if(diffDays>0){setStatus("sgStatus",`💡 Vyplnit 1–3 dny před odletem (zbývá cca ${diffDays} dní)`);setStatus("voaStatus",`💡 Možno vyřídit online předem (cesta za ${diffDays} dní)`);setStatus("levyStatus",`💡 Doporučeno uhradit předem online`);setStatus("ecdStatus",`💡 Vyplnit 2 dny před příletem`)}else{setStatus("sgStatus",`✅ Čas na vyplnění (1–3 dny před příletem)`);setStatus("voaStatus",`✅ Aktivní pro vyřízení`);setStatus("levyStatus",`✅ Připraveno k úhradě`);setStatus("ecdStatus",`✅ Aktivní pro vyplnění`)}});